CREATE TYPE "CoinLedgerType" AS ENUM ('PURCHASE','GIFT_SPENT','ADJUSTMENT','REFUND');
CREATE TYPE "CoinPurchaseStatus" AS ENUM ('PENDING','PAID','FAILED','REVIEW');
ALTER TYPE "NotificationType" ADD VALUE IF NOT EXISTS 'GIFT_RECEIVED';
ALTER TYPE "NotificationType" ADD VALUE IF NOT EXISTS 'TIP_RECEIVED';
CREATE TABLE "CoinWallet" ("id" TEXT NOT NULL,"userId" TEXT NOT NULL,"balance" INTEGER NOT NULL DEFAULT 0,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "CoinWallet_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "CoinWallet_userId_key" ON "CoinWallet"("userId");
ALTER TABLE "CoinWallet" ADD CONSTRAINT "CoinWallet_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE;
CREATE TABLE "CoinLedgerEntry" ("id" TEXT NOT NULL,"walletId" TEXT NOT NULL,"userId" TEXT NOT NULL,"type" "CoinLedgerType" NOT NULL,"amount" INTEGER NOT NULL,"balanceAfter" INTEGER NOT NULL,"sourceType" TEXT,"sourceId" TEXT,"description" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "CoinLedgerEntry_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "CoinLedgerEntry_sourceType_sourceId_type_key" ON "CoinLedgerEntry"("sourceType","sourceId","type"); CREATE INDEX "CoinLedgerEntry_userId_createdAt_idx" ON "CoinLedgerEntry"("userId","createdAt");
ALTER TABLE "CoinLedgerEntry" ADD CONSTRAINT "CoinLedgerEntry_walletId_fkey" FOREIGN KEY ("walletId") REFERENCES "CoinWallet"("id") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "CoinLedgerEntry" ADD CONSTRAINT "CoinLedgerEntry_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
CREATE TABLE "CoinPackage" ("id" TEXT NOT NULL,"code" TEXT NOT NULL,"name" TEXT NOT NULL,"points" INTEGER NOT NULL,"priceAmount" INTEGER NOT NULL,"currency" VARCHAR(3) NOT NULL,"bonusPoints" INTEGER NOT NULL DEFAULT 0,"active" BOOLEAN NOT NULL DEFAULT true,"sortOrder" INTEGER NOT NULL DEFAULT 0,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "CoinPackage_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "CoinPackage_code_key" ON "CoinPackage"("code"); CREATE INDEX "CoinPackage_active_sortOrder_idx" ON "CoinPackage"("active","sortOrder");
CREATE TABLE "CoinPurchase" ("id" TEXT NOT NULL,"reference" TEXT NOT NULL,"userId" TEXT NOT NULL,"packageId" TEXT NOT NULL,"points" INTEGER NOT NULL,"grossAmount" INTEGER NOT NULL,"currency" VARCHAR(3) NOT NULL,"status" "CoinPurchaseStatus" NOT NULL DEFAULT 'PENDING',"operator" TEXT,"payerPhoneHint" TEXT,"externalRef" TEXT,"initiatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"paidAt" TIMESTAMP(3),"attempts" INTEGER NOT NULL DEFAULT 1,"reviewReason" TEXT,"providerPayload" JSONB,CONSTRAINT "CoinPurchase_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "CoinPurchase_reference_key" ON "CoinPurchase"("reference"); CREATE INDEX "CoinPurchase_userId_status_initiatedAt_idx" ON "CoinPurchase"("userId","status","initiatedAt"); CREATE INDEX "CoinPurchase_status_initiatedAt_idx" ON "CoinPurchase"("status","initiatedAt");
ALTER TABLE "CoinPurchase" ADD CONSTRAINT "CoinPurchase_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "CoinPurchase" ADD CONSTRAINT "CoinPurchase_packageId_fkey" FOREIGN KEY ("packageId") REFERENCES "CoinPackage"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
CREATE TABLE "Gift" ("id" TEXT NOT NULL,"code" TEXT NOT NULL,"name" TEXT NOT NULL,"symbol" TEXT NOT NULL,"meaning" TEXT NOT NULL,"pricePoints" INTEGER NOT NULL,"rarity" TEXT NOT NULL DEFAULT 'COMMON',"animationKey" TEXT,"imageKey" TEXT,"active" BOOLEAN NOT NULL DEFAULT true,"sortOrder" INTEGER NOT NULL DEFAULT 0,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "Gift_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "Gift_code_key" ON "Gift"("code"); CREATE INDEX "Gift_active_sortOrder_idx" ON "Gift"("active","sortOrder");
CREATE TABLE "CoinGiftTransaction" ("id" TEXT NOT NULL,"senderId" TEXT NOT NULL,"creatorId" TEXT NOT NULL,"giftId" TEXT NOT NULL,"liveId" TEXT,"quantity" INTEGER NOT NULL DEFAULT 1,"pointsSpent" INTEGER NOT NULL,"grossAmount" INTEGER NOT NULL,"platformFee" INTEGER NOT NULL,"creatorAmount" INTEGER NOT NULL,"currency" VARCHAR(3) NOT NULL,"message" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "CoinGiftTransaction_pkey" PRIMARY KEY ("id"));
CREATE INDEX "CoinGiftTransaction_creatorId_createdAt_idx" ON "CoinGiftTransaction"("creatorId","createdAt"); CREATE INDEX "CoinGiftTransaction_senderId_createdAt_idx" ON "CoinGiftTransaction"("senderId","createdAt"); CREATE INDEX "CoinGiftTransaction_liveId_createdAt_idx" ON "CoinGiftTransaction"("liveId","createdAt");
ALTER TABLE "CoinGiftTransaction" ADD CONSTRAINT "CoinGiftTransaction_senderId_fkey" FOREIGN KEY ("senderId") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "CoinGiftTransaction" ADD CONSTRAINT "CoinGiftTransaction_creatorId_fkey" FOREIGN KEY ("creatorId") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "CoinGiftTransaction" ADD CONSTRAINT "CoinGiftTransaction_giftId_fkey" FOREIGN KEY ("giftId") REFERENCES "Gift"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
CREATE TABLE "CoinTipTransaction" ("id" TEXT NOT NULL,"senderId" TEXT NOT NULL,"creatorId" TEXT NOT NULL,"amount" INTEGER NOT NULL,"platformFee" INTEGER NOT NULL,"creatorAmount" INTEGER NOT NULL,"currency" VARCHAR(3) NOT NULL,"message" TEXT,"liveId" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "CoinTipTransaction_pkey" PRIMARY KEY ("id"));
CREATE INDEX "CoinTipTransaction_creatorId_createdAt_idx" ON "CoinTipTransaction"("creatorId","createdAt"); CREATE INDEX "CoinTipTransaction_senderId_createdAt_idx" ON "CoinTipTransaction"("senderId","createdAt");
ALTER TABLE "CoinTipTransaction" ADD CONSTRAINT "CoinTipTransaction_senderId_fkey" FOREIGN KEY ("senderId") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE; ALTER TABLE "CoinTipTransaction" ADD CONSTRAINT "CoinTipTransaction_creatorId_fkey" FOREIGN KEY ("creatorId") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
